package it.cavallium.rockserver.core.client;

import it.cavallium.buffer.Buf;
import it.cavallium.rockserver.core.common.Keys;
import it.cavallium.rockserver.core.common.RequestType;
import it.cavallium.rockserver.core.common.api.*;
import it.cavallium.rockserver.core.common.distributed.*;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.thrift.*;
import org.apache.thrift.protocol.*;
import org.apache.thrift.transport.TMemoryBuffer;

/** Current mutation wire bounds and exact caller-owned identity checks. */
public final class ThriftRemoteMutationWire {
    public static final int MAX_FRAME_BYTES=RemoteMutationAsyncAPI.MAX_POINT_INPUT_BYTES+64*1024,MAX_OWNERS=4096;
    private ThriftRemoteMutationWire() {}
    public static ByteBuffer uuid(UUID value){return ByteBuffer.allocate(16).putLong(value.getMostSignificantBits()).putLong(value.getLeastSignificantBits()).flip();}
    public static UUID uuid(ByteBuffer value){if(value==null || value.remaining()!=16)throw new IllegalArgumentException("UUID must contain 16 bytes");var b=value.duplicate();return new UUID(b.getLong(),b.getLong());}
    public static byte[] bytes(ByteBuffer value,int maximum){if(value==null || value.remaining()>maximum)throw new IllegalArgumentException("Mutation binary exceeds bound");var result=new byte[value.remaining()];value.duplicate().get(result);return result;}
    public static byte[] digest(ByteBuffer value){if(value==null || value.remaining()!=32)throw new IllegalArgumentException("Digest must contain 32 bytes");return bytes(value,32);}
    public static ByteBuffer token(RemoteMutationToken value){return ByteBuffer.wrap(value.encode());}
    public static RemoteMutationToken token(ByteBuffer value){if(value==null || (value.remaining()<RemoteMutationToken.MIN_BYTES || value.remaining()>RemoteMutationToken.MAX_BYTES))throw new IllegalArgumentException("Invalid mutation token length");return RemoteMutationToken.decode(bytes(value,RemoteMutationToken.MAX_BYTES));}
    public static ThriftMutationOwner owner(RemoteMutationOwner value){return new ThriftMutationOwner(uuid(value.clusterId()),uuid(value.databaseId()),uuid(value.ownerId()),ThriftMutationKind.valueOf(value.kind().name()),value.ownerEpoch(),value.nextRequestSequence(),value.domains().stream().map(d->new ThriftMutationDomainBinding(uuid(d.domainId()),d.directoryGeneration(),ByteBuffer.wrap(d.directoryDigest()),d.schemaEpoch(),ByteBuffer.wrap(d.schemaDigest()))).toList());}
    public static RemoteMutationOwner owner(ThriftMutationOwner value){required(value);if(!value.isSetOwnerEpoch() || !value.isSetNextRequestSequence() || value.domains.size()<1 || value.domains.size()>DomainBinding.MAX_DOMAINS)throw new IllegalArgumentException("Missing owner epoch/sequence/domains");var domains=value.domains.stream().map(d->{required(d);if(!d.isSetDirectoryGeneration() || !d.isSetSchemaEpoch())throw new IllegalArgumentException("Missing binding generation/epoch");return new DomainBinding(uuid(d.domainId),d.directoryGeneration,digest(d.directoryDigest),d.schemaEpoch,digest(d.schemaDigest));}).toList();if(!domains.equals(DomainBinding.canonical(domains)))throw new IllegalArgumentException("Noncanonical owner domains");return new RemoteMutationOwner(uuid(value.clusterId),uuid(value.databaseId),uuid(value.ownerId),value.ownerEpoch,value.nextRequestSequence,RemoteMutationToken.Kind.valueOf(value.kind.name()),domains);}
    public static RemoteMutationOwner authority(ThriftMutationOwner value,RemoteMutationToken.Kind kind,long sequence){var owner=owner(value);if(owner.kind()!=kind || sequence<0)throw new IllegalArgumentException("Invalid mutation owner/sequence");return owner;}
    public static RemoteMutationToken prepared(ByteBuffer wire,RemoteMutationOwner owner,UUID request,long sequence,byte[] input){var result=token(wire);var expected=new RemoteMutationToken(owner.clusterId(),owner.databaseId(),owner.ownerId(),request,owner.ownerEpoch(),sequence,owner.kind(),owner.domains(),input);if(!result.equals(expected))throw new IllegalArgumentException("Crossed prepared mutation identity/input");return result;}
    public static List<ByteBuffer> key(Keys value){if(value==null)return null;if(value.keys().length>DistributedSchemaCodec.MAX_KEY_COMPONENTS)throw new IllegalArgumentException("Too many key components");var result=new ArrayList<ByteBuffer>();for(var part:value.keys())result.add(ByteBuffer.wrap(part.toByteArray()));return result;}
    public static Keys key(List<ByteBuffer> value){if(value==null)return null;if(value.size()>DistributedSchemaCodec.MAX_KEY_COMPONENTS)throw new IllegalArgumentException("Too many key components");long total=0;for(var part:value){Objects.requireNonNull(part);total+=part.remaining();if(total>RemoteMutationAsyncAPI.MAX_POINT_INPUT_BYTES)throw new IllegalArgumentException("Key exceeds input bound");}var parts=new Buf[value.size()];for(int i=0;i<parts.length;i++)parts[i]=Buf.wrap(bytes(value.get(i),RemoteMutationAsyncAPI.MAX_POINT_INPUT_BYTES));return new Keys(parts);}
    public static void range(List<ByteBuffer> lower,List<ByteBuffer> upper){long bytes=0;for(var bound:Arrays.asList(lower,upper)){if(bound==null)continue;if(bound.size()>DistributedSchemaCodec.MAX_KEY_COMPONENTS)throw new IllegalArgumentException("Too many range key components");for(var part:bound){bytes+=Objects.requireNonNull(part).remaining();if(bytes>TransactionScope.MAX_BOUND_BYTES)throw new IllegalArgumentException("Range bounds exceed byte budget");}}}
    public static List<ThriftMutationEntry> entries(List<Keys> keys,List<Buf> values,int items,int maximum){if(keys.size()>items || !values.isEmpty() && values.size()!=keys.size())throw new IllegalArgumentException("Invalid mutation entry count");var result=new ArrayList<ThriftMutationEntry>();long size=0;for(int i=0;i<keys.size();i++){var key=Objects.requireNonNull(keys.get(i));for(var part:key.keys())size+=4L+part.size();var value=values.isEmpty()?null:values.get(i);size+=8L+(value==null?0:value.size());if(size>maximum)throw new IllegalArgumentException("Mutation input exceeds byte bound");var entry=new ThriftMutationEntry(key(key));if(value!=null)entry.setValue(value.toByteArray());result.add(entry);}return List.copyOf(result);}
    public record Input(List<Keys> keys,List<Buf> values) {}
    public static Input entries(List<ThriftMutationEntry> entries,boolean present,int items,int maximum){if(entries==null || entries.size()>items)throw new IllegalArgumentException("Invalid mutation entry count");long size=0;for(var entry:entries){required(entry);if(entry.keys.size()>DistributedSchemaCodec.MAX_KEY_COMPONENTS)throw new IllegalArgumentException("Too many key components");for(var part:entry.keys)size+=4L+Objects.requireNonNull(part).remaining();if(!present && entry.isSetValue())throw new IllegalArgumentException("Unexpected mutation value");size+=8L+(entry.isSetValue()?entry.value.remaining():0);if(size>maximum)throw new IllegalArgumentException("Mutation input exceeds byte bound");}var keys=new ArrayList<Keys>();var values=new ArrayList<Buf>();for(var entry:entries){keys.add(key(entry.keys));if(present)values.add(entry.isSetValue()?Buf.wrap(bytes(entry.value,maximum)):null);}return new Input(List.copyOf(keys),Collections.unmodifiableList(values));}
    public static void point(List<ThriftMutationEntry> entries,boolean present,ThriftPointMutationKind kind,ThriftMutationCallback callback,boolean multi){Objects.requireNonNull(kind);Objects.requireNonNull(callback);if(entries==null || entries.isEmpty() || entries.size()>RemoteMutationAsyncAPI.MAX_POINT_ITEMS || !multi && entries.size()!=1 || present!=(kind!=ThriftPointMutationKind.DELETE))throw new IllegalArgumentException("Invalid point input shape");}
    public record AtomicInput(List<AtomicMutation> mutations,List<AtomicPredicate> predicates) {}
    private static long atomicKeySize(List<ByteBuffer> key){if(key.size()>DistributedSchemaCodec.MAX_KEY_COMPONENTS)throw new IllegalArgumentException("Atomic key component count exceeds bound");long bytes=4;for(var part:key)bytes=Math.addExact(bytes,4L+Objects.requireNonNull(part).remaining());return bytes;}
    public static AtomicInput atomic(List<ThriftAtomicMutation> mutations,List<ThriftAtomicPredicate> predicates,long ttl){
        Objects.requireNonNull(mutations);Objects.requireNonNull(predicates);if(ttl<1 || ttl>60000 || (long)mutations.size()+predicates.size()<1 || (long)mutations.size()+predicates.size()>256)throw new IllegalArgumentException("Invalid atomic count/lifetime");long size=17;
        for(var m:mutations){required(m);if(m.kind==ThriftPointMutationKind.DELETE && m.isSetValue() || m.kind==ThriftPointMutationKind.MERGE && !m.isSetValue())throw new IllegalArgumentException("Invalid atomic mutation kind/value");if(!m.isSetColumn())throw new IllegalArgumentException("Missing atomic column");size=Math.addExact(size,14+atomicKeySize(m.keys)+(m.isSetValue()?m.value.remaining():0));if(size>2*1024*1024)throw new IllegalArgumentException("Atomic input exceeds byte bound");}for(var p:predicates){required(p);if(!p.isSetColumn())throw new IllegalArgumentException("Missing atomic predicate column");size=Math.addExact(size,12+atomicKeySize(p.keys)+(p.isSetExpected()?p.expected.remaining():0));if(size>2*1024*1024)throw new IllegalArgumentException("Atomic input exceeds byte bound");}
        var writes=mutations.stream().map(m->new AtomicMutation(m.column,key(m.keys),Mutation.Kind.valueOf(m.kind.name()),m.isSetValue()?Buf.wrap(bytes(m.value,2*1024*1024)):null,Mutation.ReturnMode.valueOf(m.returns.name()))).toList();var tests=predicates.stream().map(p->new AtomicPredicate(p.column,key(p.keys),p.isSetExpected()?Buf.wrap(bytes(p.expected,2*1024*1024)):null)).toList();RemoteMutationInputs.atomicSize(writes,tests,ttl);return new AtomicInput(writes,tests);
    }
    public static List<ThriftAtomicMutation> mutations(List<AtomicMutation> values){return values.stream().map(m->{var result=new ThriftAtomicMutation(m.column(),key(m.key()),ThriftPointMutationKind.valueOf(m.kind().name()),ThriftAtomicReturnMode.valueOf(m.returns().name()));if(m.value()!=null)result.setValue(m.value().toByteArray());return result;}).toList();}
    public static List<ThriftAtomicPredicate> predicates(List<AtomicPredicate> values){return values.stream().map(p->{var result=new ThriftAtomicPredicate(p.column(),key(p.key()));if(p.expected()!=null)result.setExpected(p.expected().toByteArray());return result;}).toList();}
    private static void validateStatus(RemoteMutationStatus value){Objects.requireNonNull(value.token());Objects.requireNonNull(value.state());if(value.retainedResults()<0 || value.appliedMutations() < -1 || value.copiedBatches() < -1 || (value.appliedMutations()<0)!=(value.copiedBatches()<0) || value.resultDigest()!=null && value.resultDigest().length!=32)throw new IllegalArgumentException("Invalid mutation progress/digest");}
    public static ThriftMutationObservation status(RemoteMutationStatus value){validateStatus(value);var result=new ThriftMutationObservation(token(value.token()),ThriftMutationState.valueOf(value.state().name()),value.appliedMutations(),value.copiedBatches(),value.retainedResults());if(value.outcome()!=null)result.setOutcome(ThriftMutationOutcome.valueOf(value.outcome().name()));if(value.resultDigest()!=null)result.setResultDigest(value.resultDigest());return result;}
    public static RemoteMutationStatus status(ThriftMutationObservation value,RemoteMutationToken expected){required(value);if(!value.isSetAppliedMutations() || !value.isSetCopiedBatches() || !value.isSetRetainedResults())throw new IllegalArgumentException("Missing mutation progress");var actual=token(value.token);if(!actual.equals(expected))throw new IllegalArgumentException("Crossed mutation token");var result=new RemoteMutationStatus(actual,RemoteMutationStatus.State.valueOf(value.state.name()),value.appliedMutations,value.copiedBatches,value.retainedResults,value.isSetOutcome()?CommandResult.Status.valueOf(value.outcome.name()):null,value.isSetResultDigest()?digest(value.resultDigest):null);validateStatus(result);return result;}
    public static void budget(int offset,int items,int bytes){if(offset<0 || items<1 || items>RemoteMutationResultPage.MAX_ITEMS || bytes<1 || bytes>CommandResult.MAX_BYTES)throw new IllegalArgumentException("Invalid mutation result budget");}
    public static ThriftMutationPage page(RemoteMutationResultPage value,RemoteMutationToken expected,int offset,int items,int bytes){var rows=new ArrayList<ByteBuffer>();value.rows().forEach(row->rows.add(ByteBuffer.wrap(row)));var wire=new ThriftMutationPage(status(value.status()),value.offset(),value.nextOffset(),rows,value.hasMore());page(wire,expected,offset,items,bytes);return wire;}
    public static RemoteMutationResultPage page(ThriftMutationPage value,RemoteMutationToken expected,int offset,int items,int bytes){budget(offset,items,bytes);required(value);if(!value.isSetOffset() || !value.isSetNextOffset() || !value.isSetHasMore())throw new IllegalArgumentException("Missing mutation cursor");if(value.offset!=offset || value.rows.size()>items)throw new IllegalArgumentException("Invalid mutation result cursor/count");long size=0;for(var row:value.rows){size+=row.remaining();if(size>bytes)throw new IllegalArgumentException("Result page exceeds requested byte budget");}var rows=new ArrayList<byte[]>();for(var row:value.rows){var encoded=bytes(row,CommandResult.MAX_BYTES);CommandResult.decode(encoded);rows.add(encoded);}var page=new RemoteMutationResultPage(status(value.status,expected),offset,value.nextOffset,rows);if(value.hasMore!=page.hasMore())throw new IllegalArgumentException("Invalid mutation continuation");return page;}
    private static void required(TBase<?,?> value){Objects.requireNonNull(value);try{if(value instanceof ThriftMutationDomainBinding v)v.validate();else if(value instanceof ThriftAtomicMutation v)v.validate();else if(value instanceof ThriftAtomicPredicate v)v.validate();else if(value instanceof ThriftMutationOwner v)v.validate();else if(value instanceof ThriftMutationEntry v)v.validate();else if(value instanceof ThriftMutationObservation v)v.validate();else if(value instanceof ThriftMutationPage v)v.validate();}catch(TException failure){throw new IllegalArgumentException("Missing mutation wire fields",failure);}}
    public static long serializedSize(TBase<?,?> value)throws TException{class Counter extends TMemoryBuffer{long count;Counter()throws org.apache.thrift.transport.TTransportException{super(0);}@Override public void write(byte[] bytes,int offset,int length){count=Math.addExact(count,length);}}var counter=new Counter();value.write(new TBinaryProtocol(counter));return counter.count;}
    /** Unique field IDs bind declared binary and collection lengths before generated body allocation. */
    public static TProtocol boundedProtocol(TProtocol protocol,boolean request){return new TProtocolDecorator(protocol){private short field;private boolean atomic;private long atomicPayload;@Override public TMessage readMessageBegin()throws TException{var message=super.readMessageBegin();atomic=message.name.equals("prepareAtomic");atomicPayload=0;return message;}@Override public TField readFieldBegin()throws TException{var value=super.readFieldBegin();field=value.id;return value;}@Override public ByteBuffer readBinary()throws TException{int length=readI32();int maximum=switch(field){case 1,2,3,4,5->16;case 10,11,22,23->32;case 0,20->RemoteMutationToken.MAX_BYTES;case 45->CommandResult.MAX_BYTES;case 40,41->atomic?2*1024*1024:RemoteMutationAsyncAPI.MAX_POINT_INPUT_BYTES;case 51,52->TransactionScope.MAX_BOUND_BYTES;default->0;};if(length<0 || length>maximum)throw new TProtocolException(TProtocolException.SIZE_LIMIT,"Mutation binary exceeds field bound");if(atomic && (field==40 || field==41)){atomicPayload+=length;if(atomicPayload>2*1024*1024)throw new TProtocolException(TProtocolException.SIZE_LIMIT,"Atomic payload exceeds byte bound");}getTransport().checkReadBytesAvailable(length);var bytes=new byte[length];getTransport().readAll(bytes,0,length);return ByteBuffer.wrap(bytes);}@Override public TList readListBegin()throws TException{var list=super.readListBegin();int maximum=switch(field){case 0->request?0:MAX_OWNERS;case 40,51,52->DistributedSchemaCodec.MAX_KEY_COMPONENTS;case 12->DomainBinding.MAX_DOMAINS;case 80,81,82->256;case 42->RemoteMutationAsyncAPI.MAX_BATCH_ITEMS;case 45->RemoteMutationResultPage.MAX_ITEMS;default->0;};if(list.size<0 || list.size>maximum)throw new TProtocolException(TProtocolException.SIZE_LIMIT,"Mutation collection exceeds bound");return list;}@Override public TMap readMapBegin()throws TException{throw new TProtocolException("No mutation maps");}@Override public TSet readSetBegin()throws TException{throw new TProtocolException("No mutation sets");}};}
}
